// Mirror of the JSON contract of `ac_app` (commands, events, view models).
// Checked on the Rust side by tests in crates/ac_app; will be generated by
// tauri-specta later (issue #6).

/** A display text: translation key plus arguments for its placeholders. */
export interface UserText {
  key: string;
  args: Record<string, string>;
}

export type Command = { type: 'sendRequest'; method: string; url: string };

export type CommandAck = { type: 'runStarted'; runId: number };

export type StatusClass =
  'informational' | 'success' | 'redirection' | 'clientError' | 'serverError' | 'nonstandard';

export interface HeaderView {
  name: string;
  value: string;
}

export interface BodyView {
  text: string;
  pretty: boolean;
  truncated: boolean;
  binary: boolean;
}

export interface ResponseView {
  status: number;
  reason: string | null;
  statusClass: StatusClass;
  elapsedMs: number;
  sizeBytes: number;
  headers: HeaderView[];
  body: BodyView;
}

export type RunOutcome =
  ({ kind: 'completed' } & ResponseView) | { kind: 'failed'; error: UserText };

export type AppEvent = { type: 'runFinished'; runId: number; outcome: RunOutcome };

export function isUserText(value: unknown): value is UserText {
  return (
    typeof value === 'object' &&
    value !== null &&
    typeof (value as UserText).key === 'string' &&
    typeof (value as UserText).args === 'object'
  );
}
